import { atom, read, update } from 'claude-code'
import type { Elements, Register } from 'claude-code'

type Mood = 'idle' | 'typing' | 'tired'

// After this long in one turn, or this long with no activity, Clawd gets tired.
const LONG_TURN_MS = 5 * 60 * 1000
const LONG_IDLE_MS = 10 * 60 * 1000
const SIZE = 64

const turnStartedAt = atom({ plugin: 'clawd-buddy', key: 'turnStartedAt' } as const, null)
const lastActiveAt = atom({ plugin: 'clawd-buddy', key: 'lastActiveAt' } as const, null)
const isHidden = atom({ plugin: 'clawd-buddy', key: 'isHidden' } as const, false)

// Generated from the rendered sprites (chenyouren0318-glitch/-1): animated SVG sprite
// sheets for the app surfaces, one still PNG per mood for the terminal.
const SVG: Record<Mood, string> = {"idle": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"128\" height=\"128\" viewBox=\"0 0 128 128\"><style>@keyframes a{from{transform:translateX(0)}to{transform:translateX(-3072px)}}image{animation:a 2.000s steps(24) infinite}</style><image width=\"3072\" height=\"128\" href=\"data:image/png;base64,\"/></svg>", "typing": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"128\" height=\"128\" viewBox=\"0 0 128 128\"><style>@keyframes a{from{transform:translateX(0)}to{transform:translateX(-2048px)}}image{animation:a 1.333s steps(16) infinite}</style><image width=\"2048\" height=\"128\" href=\"data:image/png;base64,\"/></svg>", "tired": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"128\" height=\"128\" viewBox=\"0 0 128 128\"><style>@keyframes a{from{transform:translateX(0)}to{transform:translateX(-4096px)}}image{animation:a 3.200s steps(32) infinite}</style><image width=\"4096\" height=\"128\" href=\"data:image/png;base64,\"/></svg>"}
const PNG: Record<Mood, string> = {"idle": "", "typing": "", "tired": ""}

const LABEL: Record<Mood, string> = {
  idle: 'Clawd 在旁邊待命',
  typing: 'Clawd 正在努力打字…',
  tired: 'Clawd 有點累了',
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'clawd',
      description: 'Show or hide the animated Clawd above the prompt',
    })
    // Re-check the mood once a minute so "tired" can appear on its own.
    $.clock.every(60_000, () => $.ui.invalidate('ui.render'))
    if ((await read($, lastActiveAt)) === null) {
      const now = await $.clock.now()
      await update($, lastActiveAt, () => now)
    }

    return next(e)
  })

  on('command.run', { command: 'clawd' }, async $ => {
    const hidden = await update($, isHidden, v => !v)

    return { text: hidden ? 'Clawd 先休息，輸入 /clawd 再叫他出來。' : 'Clawd 回來了！' }
  })

  on('prompt.submit', async ($, e, next) => {
    const now = await $.clock.now()
    await update($, turnStartedAt, () => now)
    await update($, lastActiveAt, () => now)

    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const now = await $.clock.now()
    await update($, turnStartedAt, () => null)
    await update($, lastActiveAt, () => now)

    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || (await read($, isHidden))) {
      return next(e)
    }

    const now = await $.clock.now()
    const started = await read($, turnStartedAt)
    const active = await read($, lastActiveAt)
    let mood: Mood
    if (e.props.isWorking) {
      mood = started !== null && now - started > LONG_TURN_MS ? 'tired' : 'typing'
    } else {
      mood = active !== null && now - active > LONG_IDLE_MS ? 'tired' : 'idle'
    }

    const ui = $.ui.resolve(e)
    const { Box, Text } = ui
    let picture = null
    if (e.surface === 'terminal') {
      const { Image } = ui as unknown as Elements['terminal']
      picture = <Image key="clawd" source={{ png: PNG[mood] }} columns={8} rows={4} alt="Clawd" />
    } else if (e.surface === 'desktop' || e.surface === 'mobile') {
      const { Svg } = ui as unknown as Elements['desktop']
      picture = <Svg source={SVG[mood]} width={SIZE} height={SIZE} alt={`Clawd (${mood})`} />
    }

    return (
      <Box flexDirection="row" alignItems="center" gap={1}>
        {picture}
        <Text dimColor>{LABEL[mood]}</Text>
      </Box>
    )
  })
}
